import { describe, it, expect, vi, beforeEach } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import { safeInvoke, fireInvoke } from "@/shared/lib/core/safeInvoke";

describe("safeInvoke", () => {
  beforeEach(() => vi.mocked(invoke).mockReset());

  it("returns the resolved value on success", async () => {
    vi.mocked(invoke).mockResolvedValue(["a", "b"]);
    expect(await safeInvoke<string[]>("read_x", { limit: 5 }, [])).toEqual(["a", "b"]);
    expect(invoke).toHaveBeenCalledWith("read_x", { limit: 5 });
  });

  it("returns the fallback and observes the error on failure", async () => {
    vi.mocked(invoke).mockRejectedValueOnce(new Error("nope"));
    const onError = vi.fn();
    const r = await safeInvoke<string[]>("read_x", undefined, [], onError);
    expect(r).toEqual([]);
    expect(onError).toHaveBeenCalledOnce();
  });
});

describe("fireInvoke", () => {
  beforeEach(() => vi.mocked(invoke).mockReset());

  it("invokes with the given command + args and never throws", () => {
    vi.mocked(invoke).mockResolvedValue(undefined);
    expect(() => fireInvoke("do_x", { a: 1 })).not.toThrow();
    expect(invoke).toHaveBeenCalledWith("do_x", { a: 1 });
  });

  // THE CASE THE TEST ABOVE CANNOT SEE: `mockResolvedValue` still returns a PROMISE, so it only ever
  // exercises the happy chain. A torn-down Tauri mock returns a NON-THENABLE, and `.catch` on that raises
  // SYNCHRONOUSLY — which escaped from a timer as an uncaught exception and reddened a run in which all
  // 7,095 tests passed.
  //
  // The SYNCHRONOUS-THROW half lives in `fireInvokeSurvivesMockTeardown.test.ts` instead of here: a
  // throwing `invoke` installed in one test of a MULTI-TEST file is also reached by some other deferred
  // invoker in the environment, which fails the run for reasons unrelated to `fireInvoke` (reproduced with
  // a test that never calls it at all). Keeping that case in a single-test file asserts the guard rather
  // than the environment.
  it.each([
    ["undefined (a torn-down mock)", undefined],
    ["null", null],
    ["a number", 42],
    ["a plain object", { notAPromise: true }],
  ])("never throws when invoke returns %s", (_label, value) => {
    vi.mocked(invoke).mockReturnValue(value as never);
    expect(() => fireInvoke("do_x")).not.toThrow();
  });
});

// `fireInvoke` must not throw when `invoke` throws SYNCHRONOUSLY.
//
// A SINGLE-TEST FILE ON PURPOSE. Installing a throwing `invoke` and then running a second test in the
// same file fails for a reason that has nothing to do with `fireInvoke` — some other DEFERRED invoker in
// the environment reaches the throwing mock, reproduced with a pair where the first test never calls
// `fireInvoke` at all. Asserting the guard therefore needs a file with nothing after it; the non-thenable
// half of the same bug lives on the record's own paired test, where it is stable.
//
// The bug: `void invoke(...).catch(...)` chains `.catch` onto whatever `invoke` returned. A torn-down
// Tauri mock returns a non-thenable, and a throwing one raises before there is anything to chain — and
// callers fire this from timers and listeners, where nothing is on the stack. That escaped as an uncaught
// exception and turned a run with 7,095 PASSING tests red, blamed on an unrelated test.
import { describe, it, expect, vi } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";

describe("fireInvoke survives a backend that throws on call", () => {
  it("swallows a synchronous throw and still reports it through onError", () => {
    vi.mocked(invoke).mockReset();
    vi.mocked(invoke).mockImplementation(() => {
      throw new Error("backend gone");
    });
    const onError = vi.fn();
    expect(() => fireInvoke("do_x", { a: 1 }, onError)).not.toThrow();
    // SWALLOWED, NOT SILENT: the caller's observer still sees it, so the failure is reportable.
    expect(onError).toHaveBeenCalledOnce();
    expect(onError.mock.calls[0][0]).toBeInstanceOf(Error);
  });
});
